function compareRouterStates(a: Router['state'], b: Router['state']) {
  const aKeys = Object.keys(a);
  const aKeysLen = aKeys.length;
  if (aKeysLen !== Object.keys(b).length) return false

  // It is most likely that shapes of parsed queries are different
  const aQueryKeys = Object.keys(a.query);
  const aQueryKeysLen = aKeys.length;
  if (aQueryKeysLen !== Object.keys(b.query).length) return false
  for (let j = aQueryKeysLen; j-- !== 0;) {
    if (!Object.prototype.hasOwnProperty.call(b.query, aQueryKeys[j])) return false
  }
  // Only compare the value when shapes are the same
  for (let j = aQueryKeysLen; j-- !== 0;) {
    const queryKey = aQueryKeys[j]
    if (a.query[queryKey] !== b.query[queryKey]) return false;
  }

  for (let i = aKeysLen; i-- !== 0;) {  
    const key = aKeys[i];
    if (key === 'query') continue;

    // It is less likely that shapes of router states are different
    // So compare the shape and the value together
    if (
      !Object.prototype.hasOwnProperty.call(b, key)
      || a[key as keyof Router['state']] !== b[key as keyof Router['state']]
    ) {
      return false;
    }
  }

  return true
}
```

